function addPuppetToScene(data){const view=projectView(),width=Math.min(view.width*.7,view.height*.85*data.imageWidth/data.imageHeight),o={...structuredClone(data),id:uid(),type:'puppet',width,height:width*data.imageHeight/data.imageWidth,ease:'smooth',expression:'happy',keys:[{t:0,v:{...pose,...rigDefaults,x:480,y:270}}]};if(!validPuppet(o))return toast('This saved rig has invalid parts or joints.');current().objects.push(o);selectLayers([o.id]);save();render();return o}
$('saveImageRig').onclick=async()=>{if(!imageRigDraft.parts.length)return toast('Cut or import at least one body part first.');imageRigDraft.name=$('rigName').value.trim()||'Picture character';const data={name:imageRigDraft.name,rigGuide:imageRigDraft.rigGuide?structuredClone(imageRigDraft.rigGuide):undefined,originalImageSrc:imageRigDraft.originalImageSrc||undefined,face:imageRigDraft.face?structuredClone(imageRigDraft.face):undefined,imageSrc:imageRigDraft.imageSrc,imageWidth:imageRigDraft.imageWidth,imageHeight:imageRigDraft.imageHeight,parts:structuredClone(imageRigDraft.parts),rigNeutral:{...pose,...rigDefaults},mouth:imageRigDraft.mouth?structuredClone(imageRigDraft.mouth):null};const existing=current().objects.find(o=>o.id===rigEditId);if(existing){if(existing.locked)return;Object.assign(existing,data);save();render()}else addPuppetToScene(data);$('imageRigDialog').close();if(!existing)try{if(rigLibrary.length<20){rigLibrary.push({id:uid(),...data});await workspacePut('puppetLibrary',rigLibrary);renderRigLibrary()}}catch{toast('Character is in the project; the reusable library could not be saved.')}};
function renderRigLibrary(){const list=$('rigLibrary');list.replaceChildren();if(rigLibrary.length){const label=document.createElement('h3');label.textContent='Your rigged characters';list.append(label)}for(const entry of rigLibrary){const row=document.createElement('div');row.className='rig-library-row';const button=document.createElement('button');button.textContent='＋ '+entry.name;button.onclick=()=>addPuppetToScene(entry);const remove=document.createElement('button');remove.textContent='×';remove.title='Remove saved rig';remove.onclick=async()=>{rigLibrary=rigLibrary.filter(r=>r.id!==entry.id);await workspacePut('puppetLibrary',rigLibrary);renderRigLibrary()};row.append(button,remove);list.append(row)}}
workspaceValue('puppetLibrary').then(list=>{rigLibrary=Array.isArray(list)?list.filter(r=>r?.parts?.length&&r.imageWidth&&r.imageHeight).slice(0,20):[];renderRigLibrary()}).catch(()=>{});
const controlsBeforePuppets=renderControls;renderControls=function(){controlsBeforePuppets();const o=object();if(o?.type!=='puppet')return;const panel=document.createElement('details');panel.open=true;panel.innerHTML='<summary>Rigged picture character</summary><button id="editImageRig">Edit cut-outs & joints</button><button id="setPuppetMouth">Set mouth area</button><label>Loop<select id="puppetLoop"><option value="none">None</option><option value="idle">Idle</option><option value="walk">Walk</option><option value="talk">Talk gestures</option></select></label>'+o.parts.filter(p=>p.channel!=='none').map(p=>field(esc(p.name),p.channel,-180,180)).join('');$('controls').prepend(panel);$('editImageRig').onclick=()=>openImageRig(o);$('setPuppetMouth').onclick=()=>openImageRig(o,true);$('puppetLoop').value=o.characterLoop||'none';$('puppetLoop').onchange=e=>{if(o.locked)return;o.characterLoop=e.target.value;save();draw()};panel.querySelectorAll('[data-field]').forEach(input=>input.oninput=()=>setDisplayedFields(o,{[input.dataset.field]:+input.value}));panel.querySelectorAll('button,input,select').forEach(e=>e.disabled=!!o.locked)};
const exportBeforePuppets=$('renderVideo').onclick;$('renderVideo').onclick=async()=>{await Promise.all(project.scenes.flatMap(s=>s.objects.filter(o=>o.type==='puppet').flatMap(o=>[...o.parts.map(p=>p.src),...Object.values(o.mouth?.sprites||{})].map(imageReady))));return exportBeforePuppets()};
function validPuppet(o){if(!Number.isFinite(o.imageWidth)||o.imageWidth<1||o.imageWidth>2000||!Number.isFinite(o.imageHeight)||o.imageHeight<1||o.imageHeight>2000||!Number.isFinite(o.width)||o.width<=0||o.width>2000||!Number.isFinite(o.height)||o.height<=0||o.height>2000||!Array.isArray(o.parts)||!o.parts.length||o.parts.length>32)return false;if(o.rigNeutral&&(!Object.values(o.rigNeutral).every(Number.isFinite)))return false;const ids=new Set(o.parts.map(p=>p.id));if(ids.size!==o.parts.length)return false;const image=s=>typeof s==='string'&&s.length<12e6&&s.startsWith('data:image/png;base64,');if(o.imageSrc&&!image(o.imageSrc))return false;for(const p of o.parts)if(typeof p.id!=='string'||typeof p.name!=='string'||p.name.length>80||!Object.hasOwn(rigRoles,p.role)||!['none','headTilt','leftArm','leftElbow','rightArm','rightElbow','leftLeg','leftKnee','rightLeg','rightKnee'].includes(p.channel)||!['x','y','width','height','pivotX','pivotY'].every(k=>Number.isFinite(p[k])&&Math.abs(p[k])<=10000)||p.width<=0||p.height<=0||!image(p.src)||p.parentId&&!ids.has(p.parentId)||!canParentRig(o.parts,p.id,p.parentId))return false;const m=o.mouth;if(m&&(!['x','y','w','h'].every(k=>Number.isFinite(m[k])&&Math.abs(m[k])<=10000)||m.w<=0||m.h<=0||!/^#[0-9a-f]{6}$/i.test(m.color)||m.parentId&&!ids.has(m.parentId)||m.sprites&&Object.entries(m.sprites).some(([key,src])=>!/^[A-HX]$/.test(key)||!image(src))))return false;return true}
const puppetValidator=valid;valid=function(p){return puppetValidator(p)&&p.scenes.every(s=>s.objects.every(o=>o.type!=='puppet'||validPuppet(o)))};
const thumbnailBeforePuppets=renderStoryThumbnail;renderStoryThumbnail=async function(canvas,s){await Promise.all(s.objects.filter(o=>o.type==='puppet').flatMap(o=>[...o.parts.map(p=>p.src),...Object.values(o.mouth?.sprites||{})].map(src=>imageReady(src).catch(()=>{}))));return thumbnailBeforePuppets(canvas,s)};
render();
